mapper.select:
SELECT MAX(${column})FROM ${tblName}
    WHERE TO_CHAR(${orgCol}) IN (
        SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
            WHERE ORGTYPE = 0 START WITH FATHERORGID = #{orgid} CONNECT BY PRIOR FATHERORGID = ORGID
        UNION ALL
        SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
            WHERE ORGID = #{orgid}
        UNION ALL
        SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
            WHERE ORGTYPE >= 100 START WITH FATHERORGID = -1 CONNECT BY PRIOR ORGID = FATHERORGID
    )

    AND ${column} LIKE '${jgf}'
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),#{orgNosepartor},'')
        )
    ) = 1


    AND ${column} LIKE '${jgf}'
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),'-','')
        )
    ) = 0
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),'_','')
        )
    )  = 0
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),',','')
        )
    )  = 0
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),'.','')
        )
    )  = 0
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH
            (REPLACE(REPLACE${column},#{orgNocode},''),'`','')
        )
    )  = 0
    AND (
        LENGTH(
            REPLACE(${column},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${column},#{orgNocode},''),'~','')
        )
    )  = 0

 ${chChoiceCol} ${bjf} ${choiceVal}

SELECT MAX(${chilNumberCol}) FROM ${chilTblName}
    WHERE ${chilParentCol}
IN (
    SELECT ${parentIdCol} FROM${parentTblName}
        WHERE
        ${parnetOrgCol}
        IN(
        SELECT ORGID FROM TBL_ORGANIZATION
        WHERE ORGTYPE = 0 START WITH FATHERORGID = #{orgid} CONNECT BY PRIOR FATHERORGID = ORGID
        UNION ALL
        SELECT ORGID FROM TBL_ORGANIZATION
        WHERE ORGID = #{orgid}
        UNION ALL
                    SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
                        WHERE ORGTYPE >=100 START WITH FATHERORGID = -1 CONNECT BY PRIOR ORGID = FATHERORGID

            )


        SELECT ${middleChilCol} FROM ${middleTblname}
        WHERE ${middleParentCol}
        IN (
        SELECT ${parentIdCol} FROM ${parentTblName}
            WHERE
            ${parnetOrgCol}
            IN (
                SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
                    WHERE ORGTYPE = 0 START WITH FATHERORGID = #{orgid} CONNECT BY PRIOR FATHERORGID = ORGID
                UNION ALL
                SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
                    WHERE ORGID = #{orgid}
                UNION ALL
                    SELECT TO_CHAR(ORGID) FROM TBL_ORGANIZATION
                    WHERE ORGTYPE >=100 START WITH FATHERORGID = -1 CONNECT BY PRIOR ORGID = FATHERORGID

            )
        )

)

    AND ${chilNumberCol} LIKE '${jgf}'
    AND (
        LENGTH(
            REPLACE(${chilNumberCol},#{orgNocode},'')
        ) -
        LENGTH(
            REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),#{orgNosepartor},'')
        )
    ) = 1


    AND ${chilNumberCol} LIKE '${jgf}'
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),'-',''))) = 0
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),'_',''))) = 0
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),',',''))) = 0
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),'`',''))) = 0
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),'.',''))) = 0
    AND (LENGTH(REPLACE(${chilNumberCol},#{orgNocode},'')) - LENGTH(REPLACE(REPLACE(${chilNumberCol},#{orgNocode},''),'~',''))) = 0
